	cv1, _ := r.Cargo("G1")
	cv2, _ := r.Cargo("G2")
	if cv1.CompartmentID != "C2" || cv2.CompartmentID != "C1" {
		t.Fatalf("交换后货物归属错误: %+v %+v", cv1, cv2)
	}
	cpt1, _ := r.Compartment("C1")
	cpt2, _ := r.Compartment("C2")
	if cpt1.UsedWeight != 30 || cpt2.UsedWeight != 30 {
