625		res1.Rejections[0].OffendingCargo[0] = "HACKED"
626		res1.Rejections[0].Destinations[0].CargoIDs[0] = "HACKED"
627	
628		res2, err := r.Preview(ops)
629		if err != nil {
630			t.Fatal(err)
631		}
632		if res2.Submittable {
633			t.Fatal("新预览不应被污染，仍应不可提交")
634		}
635		if res2.CargoChanges[0].CargoID == "HACKED" ||
636			res2.Compartments[0].After.UsedWeight == 9999 ||
637			res2.Compartments[0].After.Cargo[0].ID == "HACKED" ||
638			res2.Rejections[0].CompartmentID == "HACKED" ||
639			res2.Rejections[0].OffendingCargo[0] == "HACKED" ||
640			res2.Rejections[0].Destinations[0].CargoIDs[0] == "HACKED" {
641			t.Fatalf("调用方修改返回内容污染了后续预览: %+v", res2)
642		}
643		// 登记处本身也未受影响。
644		cv, _ := r.Cargo("G1")
645		if cv.Loaded {
646			t.Fatalf("货物仍应未装载: %+v", cv)
647		}
648	}
649	
650	func TestPreviewDoesNotTouchAdjustmentRecords(t *testing.T) {
651		r := NewRegistry()
652		if err := r.RegisterCompartment("C1", 100); err != nil {
653			t.Fatal(err)
654		}
655		if err := r.RegisterCargo("G1", 10, "X", true); err != nil {
656			t.Fatal(err)
657		}
658		ops := []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}
659		for i := 0; i < 3; i++ {
660			if _, err := r.Preview(ops); err != nil {
661				t.Fatal(err)
662			}
663		}
664		// 预览不占用编号：A1 首次正式提交即成功，而非编号冲突。
665		res := mustAdjust(t, r, "A1", ops)
666		if res.ID != "A1" || res.CargoChanges[0].To != "C1" {
667			t.Fatalf("正式提交应正常成功: %+v", res)
668		}
669		// 再次预览反映的是 A1 之后的同一时刻配载：G1 已装载，再装为状态不符。
670		requireError(t, func() error {
671			_, e := r.Preview(ops)
672			return e
673		}(), ErrStateMismatch)
674	}
675	
676	func TestPreviewConcurrentWithAdjust(t *testing.T) {
677		r := NewRegistry()
678		if err := r.RegisterCompartment("C1", 1000); err != nil {
679			t.Fatal(err)
680		}
681		if err := r.RegisterCargo("G1", 10, "X", true); err != nil {
682			t.Fatal(err)
683		}
684		done := make(chan struct{})
685		go func() {
686			defer close(done)
687			for i := 0; i < 100; i++ {
688				_, _ = r.Preview([]Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})
689				_, _ = r.Compartment("C1")
690				_, _ = r.Cargo("G1")
691			}
692		}()
693		// 与预览并发的正式调整：相同编号与内容走幂等，均返回成功且不报错、不崩溃，
694		// 但配载只真正变化一次。
695		var ok int
696		for i := 0; i < 100; i++ {
697			if _, err := r.Adjust("A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}}); err == nil {
698				ok++
699			}
700		}
701		<-done
702		if ok != 100 {
703			t.Fatalf("幂等重提应全部返回首次成功，实际成功 %d 次", ok)
704		}
705		cpt, _ := r.Compartment("C1")
706		if cpt.UsedWeight != 10 || !reflect.DeepEqual(cargoIDs(*cpt), []string{"G1"}) {
707			t.Fatalf("并发后最终配载错误: %+v", cpt)
708		}
709	}
